public void testProcessForTableStorage() throws Exception {
    Feed inFeed = (Feed) EntityType.FEED.getUnmarshaller().unmarshal(this.getClass().getResource("/config/feed/hive-table-feed.xml"));
    getStore().publish(EntityType.FEED, inFeed);
    Feed outFeed = (Feed) EntityType.FEED.getUnmarshaller().unmarshal(this.getClass().getResource("/config/feed/hive-table-feed-out.xml"));
    getStore().publish(EntityType.FEED, outFeed);
    Process process = parser.parse(ProcessEntityParserTest.class.getResourceAsStream("/config/process/process-table.xml"));
    Input input = process.getInputs().getInputs().get(0);
    Assert.assertFalse(input.isOptional());
