@Test
public void testProcessMessageCreator() throws Exception {
    Thread t = new Thread() {

        @Override
        public void run() {
            try {
                consumer();
            } catch (AssertionError e) {
                error = e;
            } catch (JMSException ignore) {
                error = null;
            }
        }
    };
    t.start();
    Thread.sleep(100);
    new MessageProducer().run(this.args);
    t.join();
    if (error != null) {
        throw error;
    }
}

