        FeedEvictor.main(new String[] { "-feedBasePath", dataPath, "-retentionType", "instance", "-retentionLimit", "days(10)", "-timeZone", "UTC", "-frequency", "daily", "-logFile", logFile, "-falconFeedStorageType", Storage.TYPE.FILESYSTEM.name() });
