@Test
public void testReInstatePartition() throws Exception {
    Map<String, String> partitionSpec = new HashMap<String, String>();
    partitionSpec.put("ds", "20130918");
    partitionSpec.put("region", "blah");
    HCatAddPartitionDesc first = HCatAddPartitionDesc.create(DATABASE_NAME, TABLE_NAME, null, partitionSpec).build();
    client.addPartition(first);
    CatalogPartition partition = CatalogServiceFactory.getCatalogService().getPartition(METASTORE_URL, DATABASE_NAME, TABLE_NAME, partitionSpec);
    Assert.assertNotNull(partition);
    final long originalCreateTime = partition.getCreateTime();
    // sleep before deletion
    Thread.sleep(1000);
    client.dropPartitions(DATABASE_NAME, TABLE_NAME, partitionSpec, true);
    // sleep so the next add is delayed a bit
    Thread.sleep(1000);
    HCatAddPartitionDesc second = HCatAddPartitionDesc.create(DATABASE_NAME, TABLE_NAME, null, partitionSpec).build();
    client.addPartition(second);
    CatalogPartition reInstatedPartition = CatalogServiceFactory.getCatalogService().getPartition(METASTORE_URL, DATABASE_NAME, TABLE_NAME, partitionSpec);
    Assert.assertNotNull(reInstatedPartition);
    final long reInstatedCreateTime = reInstatedPartition.getCreateTime();
    Assert.assertTrue(reInstatedCreateTime > originalCreateTime);
}

